class DisjointSet {
  constructor(values) {
    this.parent = new Map();
    this.rank = new Map();

    for (const value of values) {
      this.parent.set(value, value);
      this.rank.set(value, 0);
    }
  }

  find(value) {
    const parent = this.parent.get(value);

    if (parent !== value) {
      this.parent.set(value, this.find(parent));
    }

    return this.parent.get(value);
  }

  union(left, right) {
    const leftRoot = this.find(left);
    const rightRoot = this.find(right);

    if (leftRoot === rightRoot) {
      return false;
    }

    const leftRank = this.rank.get(leftRoot);
    const rightRank = this.rank.get(rightRoot);

    if (leftRank < rightRank) {
      this.parent.set(leftRoot, rightRoot);
    } else if (leftRank > rightRank) {
      this.parent.set(rightRoot, leftRoot);
    } else {
      this.parent.set(rightRoot, leftRoot);
      this.rank.set(leftRoot, leftRank + 1);
    }

    return true;
  }
}

export function minimumSpanningTree(graph) {
  const tree = graph.cloneWithNodesOnly();
  const disjointSet = new DisjointSet(graph.nodes());
  const weightedEdges = graph
    .edges()
    .map(([source, target, attributes], index) => ({
      source,
      target,
      weight: attributes.weight,
      index,
    }))
    .sort((left, right) => {
      if (left.weight !== right.weight) {
        return left.weight - right.weight;
      }

      return left.index - right.index;
    });

  for (const edge of weightedEdges) {
    if (edge.source === edge.target) {
      continue;
    }

    if (disjointSet.union(edge.source, edge.target)) {
      tree.addEdge(edge.source, edge.target, { weight: edge.weight });
    }
  }

