function runDijkstra(graph, source) {
  if (!graph.hasNode(source)) {
    throw new Error(`Source node not in graph: ${source}`);
  }

  const nodes = graph.nodes();
  const distances = new Map();
  const previous = new Map();
  const visited = new Set();

  for (const node of nodes) {
    distances.set(node, Infinity);
  }

  distances.set(source, 0);

  while (visited.size < nodes.length) {
    let currentNode = null;
    let currentDistance = Infinity;

    for (const node of nodes) {
      if (visited.has(node)) {
        continue;
      }

      const distance = distances.get(node);

      if (distance < currentDistance) {
        currentDistance = distance;
        currentNode = node;
      }
    }

    if (currentNode === null || currentDistance === Infinity) {
      break;
    }

    visited.add(currentNode);

    for (const neighbor of graph.neighbors(currentNode)) {
      if (visited.has(neighbor)) {
        continue;
      }

      const edgeData = graph.getEdgeData(currentNode, neighbor);
      const candidateDistance = currentDistance + edgeData.weight;

      if (candidateDistance < distances.get(neighbor)) {
        distances.set(neighbor, candidateDistance);
        previous.set(neighbor, currentNode);
      }
    }
  }

  return { distances, previous };
}

function buildPath(previous, source, target) {
  const path = [target];
  let currentNode = target;

  while (currentNode !== source) {
    currentNode = previous.get(currentNode);

    if (currentNode === undefined) {
      throw new Error(`No path between ${source} and ${target}`);
    }

    path.push(currentNode);
  }

  path.reverse();
  return path;
}

export function dijkstraPathLength(graph, source, target) {
  if (source === target) {
    return 0;
  }

  const { distances } = runDijkstra(graph, source);
  const distance = distances.get(target);

  if (distance === undefined || distance === Infinity) {
    throw new Error(`No path between ${source} and ${target}`);
  }

  return distance;
}

export function dijkstraPath(graph, source, target) {
  if (!graph.hasNode(target)) {
    throw new Error(`Target node not in graph: ${target}`);
  }

  if (source === target) {
    return [source];
  }

  const { distances, previous } = runDijkstra(graph, source);
  const distance = distances.get(target);

  if (distance === undefined || distance === Infinity) {
    throw new Error(`No path between ${source} and ${target}`);
  }

  return buildPath(previous, source, target);
}

