export function formatPythonValue(value) {
  if (value instanceof PythonTuple) {
    if (value.values.length === 1) {
      return `(${formatPythonValue(value.values[0])},)`;
    }

    return `(${value.values.map((item) => formatPythonValue(item)).join(", ")})`;
  }

  if (Array.isArray(value)) {
    return `[${value.map((item) => formatPythonValue(item)).join(", ")}]`;
  }

  if (typeof value === "boolean") {
    return value ? "True" : "False";
  }

  if (typeof value === "number") {
    return Number.isInteger(value) ? String(value) : String(value);
  }

  if (value === null) {
