function isConnected(graph) {
  const nodes = graph.nodes();

  if (nodes.length === 0) {
    return false;
  }

  const visited = new Set([nodes[0]]);
  const queue = [nodes[0]];

  for (let index = 0; index < queue.length; index += 1) {
    const node = queue[index];

    for (const neighbor of graph.neighbors(node)) {
      if (visited.has(neighbor)) {
        continue;
      }

      visited.add(neighbor);
      queue.push(neighbor);
    }
  }

  return visited.size === nodes.length;
}

function inNode(node) {
  return `${node}\u0000in`;
}

function outNode(node) {
  return `${node}\u0000out`;
}

function ensureResidualNode(residual, node) {
  if (!residual.has(node)) {
    residual.set(node, new Map());
  }
}

function addResidualEdge(residual, source, target, capacity) {
  ensureResidualNode(residual, source);
  ensureResidualNode(residual, target);

  const forwardEdges = residual.get(source);
  forwardEdges.set(target, (forwardEdges.get(target) ?? 0) + capacity);

  if (!residual.get(target).has(source)) {
    residual.get(target).set(source, 0);
  }
}

function buildResidualNetwork(graph, source, target) {
  const residual = new Map();
  const infinity = graph.numberOfNodes() + graph.numberOfEdges() + 1;

  for (const node of graph.nodes()) {
    const capacity = node === source || node === target ? infinity : 1;
    addResidualEdge(residual, inNode(node), outNode(node), capacity);
  }

  for (const [left, right] of graph.edges()) {
    if (left === right) {
      continue;
    }

    addResidualEdge(residual, outNode(left), inNode(right), infinity);
    addResidualEdge(residual, outNode(right), inNode(left), infinity);
  }

  return {
    residual,
    sourceNode: outNode(source),
    targetNode: inNode(target),
  };
}

function findAugmentingPath(residual, source, target) {
  const queue = [source];
  const parents = new Map([[source, null]]);

  for (let index = 0; index < queue.length; index += 1) {
    const node = queue[index];

    for (const [neighbor, capacity] of residual.get(node) ?? []) {
      if (capacity <= 0 || parents.has(neighbor)) {
        continue;
      }

      parents.set(neighbor, node);

      if (neighbor === target) {
        let bottleneck = Infinity;
        let current = target;

        while (parents.get(current) !== null) {
          const previous = parents.get(current);
          bottleneck = Math.min(bottleneck, residual.get(previous).get(current));
          current = previous;
        }

        return { parents, bottleneck };
      }

      queue.push(neighbor);
    }
  }

  return null;
}

function maxFlow(residual, source, target) {
  let flow = 0;

  while (true) {
    const path = findAugmentingPath(residual, source, target);

    if (!path) {
      return flow;
    }

    flow += path.bottleneck;
    let current = target;

    while (path.parents.get(current) !== null) {
      const previous = path.parents.get(current);
      residual.get(previous).set(current, residual.get(previous).get(current) - path.bottleneck);
      residual.get(current).set(previous, residual.get(current).get(previous) + path.bottleneck);
      current = previous;
    }
  }
}

function localNodeConnectivity(graph, source, target) {
  const network = buildResidualNetwork(graph, source, target);
  return maxFlow(network.residual, network.sourceNode, network.targetNode);
}

export function nodeConnectivity(graph) {
  const nodes = graph.nodes();

  if (nodes.length === 0) {
    return 0;
  }

  if (!isConnected(graph)) {
    return 0;
  }

  if (nodes.length === 1) {
    return graph.degree(nodes[0]);
  }

  let minimum = Infinity;

  for (let leftIndex = 0; leftIndex < nodes.length; leftIndex += 1) {
    for (let rightIndex = leftIndex + 1; rightIndex < nodes.length; rightIndex += 1) {
      const connectivity = localNodeConnectivity(graph, nodes[leftIndex], nodes[rightIndex]);

      if (connectivity < minimum) {
        minimum = connectivity;
      }
    }
  }

  return minimum === Infinity ? 0 : minimum;
}

