const ARGUMENTS = [
  { name: "a", option: "--a", metavar: "A" },
  { name: "b", option: "--b", metavar: "B" },
  { name: "c", option: "--c", metavar: "C" },
  { name: "d", option: "--d", metavar: "D" },
  { name: "e", option: "--e", metavar: "E" },
];

const ARGUMENT_MAP = new Map(ARGUMENTS.map((argument) => [argument.option, argument]));

function splitLongOption(token) {
  const separatorIndex = token.indexOf("=");

  if (separatorIndex === -1) {
    return { option: token, value: null, hasInlineValue: false };
  }

  return {
    option: token.slice(0, separatorIndex),
    value: token.slice(separatorIndex + 1),
    hasInlineValue: true,
  };
}

function isIntegerLiteral(token) {
  return /^[+-]?\d+$/.test(token);
}

function usageLine(programName) {
  return `usage: ${programName} [-h] --a A --b B --c C --d D --e E`;
}

function helpText(programName) {
  return `${usageLine(programName)}

options:
  -h, --help  show this help message and exit
  --a A
  --b B
  --c C
  --d D
  --e E
`;
}

function errorText(programName, message) {
  return `${usageLine(programName)}
${programName}: error: ${message}
`;
}

export class CliExit extends Error {
  constructor(code, streamName, text) {
    super(text);
    this.code = code;
    this.streamName = streamName;
    this.text = text;
  }
}

export function getProgramName(scriptPath) {
  const normalized = String(scriptPath ?? "").replace(/\\/g, "/");
  const parts = normalized.split("/");
  return parts[parts.length - 1] || "test10.mjs";
}

export function parseArgs(argv, { programName = "test10.mjs" } = {}) {
  const values = {};
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === "-h" || token === "--help") {
      throw new CliExit(0, "stdout", helpText(programName));
    }

    if (token === "-" || !token.startsWith("-")) {
      extras.push(token);
      continue;
    }

    const parsedOption = splitLongOption(token);
    const argument = ARGUMENT_MAP.get(parsedOption.option);

    if (!argument) {
      extras.push(token);
      continue;
    }

    let value;

    if (parsedOption.hasInlineValue) {
      value = parsedOption.value;
    } else {
      const nextToken = argv[index + 1];

      if (nextToken === undefined) {
        throw new CliExit(2, "stderr", errorText(programName, `argument ${argument.option}: expected one argument`));
      }

      if (nextToken.startsWith("-") && !isIntegerLiteral(nextToken)) {
        throw new CliExit(2, "stderr", errorText(programName, `argument ${argument.option}: expected one argument`));
      }

      value = nextToken;
      index += 1;
    }

    if (!isIntegerLiteral(value)) {
      throw new CliExit(2, "stderr", errorText(programName, `argument ${argument.option}: invalid int value: '${value}'`));
    }

    values[argument.name] = Number.parseInt(value, 10);
  }

  if (extras.length > 0) {
    throw new CliExit(2, "stderr", errorText(programName, `unrecognized arguments: ${extras.join(" ")}`));
  }

  const missingArguments = ARGUMENTS
    .filter((argument) => !(argument.name in values))
    .map((argument) => argument.option);

  if (missingArguments.length > 0) {
    throw new CliExit(
      2,
      "stderr",
      errorText(programName, `the following arguments are required: ${missingArguments.join(", ")}`),
    );
  }

  return values;
}

