function edgeKey(a, b) {
  return a <= b ? `${a}\u0000${b}` : `${b}\u0000${a}`;
}

export class Graph {
  constructor() {
    this._adjacency = new Map();
    this._edges = new Map();
  }

  addNode(node) {
    if (!this._adjacency.has(node)) {
      this._adjacency.set(node, new Map());
    }
  }

  addEdge(source, target, attributes = {}) {
    this.addNode(source);
    this.addNode(target);

    const key = edgeKey(source, target);
    let record = this._edges.get(key);

    if (!record) {
      record = {
        source,
        target,
        attributes: { ...attributes },
        order: this._edges.size,
      };
      this._edges.set(key, record);
    } else {
      Object.assign(record.attributes, attributes);
    }

    this._adjacency.get(source).set(target, record.attributes);
    this._adjacency.get(target).set(source, record.attributes);
  }

  addWeightedEdgesFrom(weightedEdges) {
    for (const [source, target, weight] of weightedEdges) {
      this.addEdge(source, target, { weight });
    }
  }

  nodes() {
    return Array.from(this._adjacency.keys());
  }

  edges() {
    return Array.from(this._edges.values())
      .sort((left, right) => left.order - right.order)
      .map((record) => [record.source, record.target, record.attributes]);
  }

  neighbors(node) {
    return this._adjacency.has(node)
      ? Array.from(this._adjacency.get(node).keys())
      : [];
  }

  hasNode(node) {
    return this._adjacency.has(node);
  }

  hasEdge(source, target) {
    return this._adjacency.get(source)?.has(target) ?? false;
  }

  getEdgeData(source, target) {
    return this._adjacency.get(source)?.get(target);
  }

  numberOfNodes() {
    return this._adjacency.size;
  }

  numberOfEdges() {
    return this._edges.size;
  }

  degree(node) {
    let total = 0;

    for (const neighbor of this.neighbors(node)) {
      total += neighbor === node ? 2 : 1;
    }

    return total;
  }

  cloneWithNodesOnly() {
    const graph = new Graph();

    for (const node of this.nodes()) {
      graph.addNode(node);
    }

    return graph;
  }
}

